"""Offline same-seed placement/platform comparison, all 40 cases retained."""
import gzip,hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT))
from metrics import stats,aggregate
from module_classes import build
from mapgen import ModuleLibrary
lib=ModuleLibrary.from_zip(ROOT/'.cache/legacy-real-v2/modules.zip',expected_sha256='5ad5a7871941b2c1ffa759b18f7b1e80f2fe7e571b72f95d1e0ef26031f08723');classes=build(lib)
old=ROOT/'validation/performance-0.4.1/final/replay';new=ROOT/'validation/runtime-iteration-20261104/varied-v3';names=[r['case'] for r in json.loads((new/'summary.json').read_text())['records'] if r['case'].startswith(('calibration-','validation-'))]
def load(root,name):return json.loads(gzip.decompress((root/(name+'.json.gz')).read_bytes()))['result']
def view(result):
 m=result['map']
 return {'bounds':m['bounds_blocks'],'instances':[dict(id=i['id'],module=i['module_id'],role=i['role'],origin=i['origin_blocks'],size=i['size_blocks'],mirror=i['transform']['mirror_x'],seals=[s['rect_pixels'] for s in i['seals']],platforms=result['content_store'][i['content_ref']]['platforms'],oneway=result['content_store'][i['content_ref']]['one_way_platform_indices'],claims=[r.get('region') for r in result['content_store'][i['content_ref']]['reward_sites']]) for i in m['instances']]}
rows=[];oldstats=[];newstats=[];maps=[]
for name in names:
 a=load(old,name);b=load(new,name);sa=stats(a,classes);sb=stats(b,classes);oldstats.append(sa);newstats.append(sb)
 rows.append({'case':name,'old':{k:v for k,v in sa.items() if k not in ['mask','modules','pairs','signature']},'new':{k:v for k,v in sb.items() if k not in ['mask','modules','pairs','signature']},'old_expansions':a['metrics']['expansions'],'new_expansions':b['metrics']['expansions'],'layout_changed':sa['signature']!=sb['signature']})
 maps.append({'case':name,'old':view(a),'new':view(b),'old_stats':rows[-1]['old'],'new_stats':rows[-1]['new']})
report={'status':'PASS','cases':len(rows),'old':aggregate(oldstats),'new':aggregate(newstats),'rows':rows,'scope':'ordinary source IDs, mirror-folded source platform/Port-Route classes, neighbor pairs and normalized occupancy; no physical or subjective playability proof'}
out=ROOT/'runtime_iteration/comparisons';out.mkdir(exist_ok=True);(out/'metrics.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
